(function(){
"use strict";
var hero=document.getElementById('coin-hero');
var hctx=hero.getContext('2d');
var HW=hero.width, HH=hero.height;

var MATS={
 gold:{base:'#c9a227',light:'#f0cf5a',hi:'#fff8c4',dark:'#6e4f08',edge:'#3d2c04',rim:'#8a6410'},
 bronze:{base:'#a86a2c',light:'#e8a85c',hi:'#ffe6bb',dark:'#542806',edge:'#3a1c05',rim:'#6e3d0e'},
 silver:{base:'#a9b1bd',light:'#e6ecf4',hi:'#ffffff',dark:'#525b68',edge:'#2e343d',rim:'#7b8492'},
 black:{base:'#23262f',light:'#4d5465',hi:'#c2d0e8',dark:'#04050a',edge:'#000000',rim:'#5a657c'}
};

function rot(x,y,z,cY,sY,cP,sP){
  var y1=y*cP - z*sP, z1=y*sP + z*cP;
  return {X:x*cY+z1*sY, Y:y1, Z:-x*sY+z1*cY};
}
function hull(points){
  var p=points.slice().sort(function(a,b){return a.x===b.x?a.y-b.y:a.x-b.x;});
  function cross(o,a,b){return (a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x);}
  var lo=[],hi=[];
  for(var i=0;i<p.length;i++){while(lo.length>=2&&cross(lo[lo.length-2],lo[lo.length-1],p[i])<=0)lo.pop();lo.push(p[i]);}
  for(var i=p.length-1;i>=0;i--){while(hi.length>=2&&cross(hi[hi.length-2],hi[hi.length-1],p[i])<=0)hi.pop();hi.push(p[i]);}
  lo.pop();hi.pop();return lo.concat(hi);
}
function circText(ctx,text,radius,font,fill,emb){
  ctx.save();ctx.font=font;ctx.textAlign='center';ctx.textBaseline='middle';
  var n=text.length;
  for(var i=0;i<n;i++){
    var a=-Math.PI/2 + (i-(n-1)/2)*(Math.PI*1.55/Math.max(1,n));
    // spread around top; caller rotates for bottom
    ctx.save();ctx.rotate(a);ctx.translate(0,-radius);
    if(emb){ctx.fillStyle='rgba(0,0,0,.55)';ctx.fillText(text[i],1.5,2);ctx.fillStyle='rgba(255,255,255,.6)';ctx.fillText(text[i],-1,-1);}
    ctx.fillStyle=fill;ctx.fillText(text[i],0,0);ctx.restore();
  }
  ctx.restore();
}
function drawFace(ctx,cx,cy,rx,ry,R,mat,isFront,yaw,pitch,nz){
  var sx=Math.max(0.02,rx/R), sy=Math.max(0.02,ry/R);
  ctx.save();ctx.translate(cx,cy);ctx.scale(sx,sy);
  // base metallic
  var g=ctx.createRadialGradient(-R*0.35,-R*0.35,R*0.05,0,0,R);
  g.addColorStop(0,mat.hi);g.addColorStop(0.28,mat.light);g.addColorStop(0.62,mat.base);g.addColorStop(0.88,mat.dark);g.addColorStop(1,mat.edge);
  ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
  // darken when tilted
  var tiltDark=Math.min(0.55,Math.abs(1-Math.abs(nz))*0.7);
  if(tiltDark>0.02){ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fillStyle='rgba(0,0,0,'+tiltDark.toFixed(3)+')';ctx.fill();}
  // raised outer rim
  ctx.lineWidth=R*0.07;ctx.beginPath();ctx.arc(0,0,R*0.94,0,Math.PI*2);ctx.strokeStyle=mat.dark;ctx.stroke();
  ctx.lineWidth=R*0.028;ctx.beginPath();ctx.arc(0,0,R*0.90,0,Math.PI*2);ctx.strokeStyle=mat.hi;ctx.stroke();
  ctx.lineWidth=R*0.02;ctx.beginPath();ctx.arc(0,0,R*0.80,0,Math.PI*2);ctx.strokeStyle='rgba(0,0,0,.45)';ctx.stroke();
  // clip for art
  ctx.save();ctx.beginPath();ctx.arc(0,0,R*0.86,0,Math.PI*2);ctx.clip();
  // brushed lines
  ctx.globalAlpha=0.10;ctx.strokeStyle='#000';
  for(var b=-R;b<R;b+=7){ctx.beginPath();ctx.moveTo(-R,b);ctx.lineTo(R,b- R*0.25);ctx.lineWidth=1;ctx.stroke();}
  ctx.globalAlpha=1;
  function embossFill(txt,x,y,font,main){
    ctx.font=font;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillStyle='rgba(0,0,0,.6)';ctx.fillText(txt,x+2,y+3);
    ctx.fillStyle='rgba(255,255,255,.65)';ctx.fillText(txt,x-1.5,y-1.5);
    ctx.fillStyle=main;ctx.fillText(txt,x,y);
  }
  if(isFront){
    circText(ctx,'WASTEDTOKEN',R*0.66,'700 '+Math.round(R*0.11)+'px Georgia,serif',mat.edge,true);
    ctx.save();ctx.rotate(Math.PI);circText(ctx,'• MINT • 2026 •',R*0.66,'700 '+Math.round(R*0.10)+'px Georgia,serif',mat.edge,true);ctx.restore();
    // medallion
    var mg=ctx.createRadialGradient(0,-R*0.1,R*0.05,0,0,R*0.55);
    mg.addColorStop(0,mat.hi);mg.addColorStop(0.5,mat.light);mg.addColorStop(1,mat.dark);
    ctx.beginPath();ctx.arc(0,R*0.02,R*0.48,0,Math.PI*2);ctx.fillStyle=mg;ctx.fill();
    ctx.lineWidth=R*0.02;ctx.strokeStyle=mat.edge;ctx.stroke();
    embossFill('W',0,-R*0.04,'900 '+Math.round(R*0.52)+'px Georgia,serif',mat.edge);
    embossFill('◆',0,R*0.32,'700 '+Math.round(R*0.10)+'px Georgia,serif',mat.edge);
    embossFill('★        ★',0,R*0.02,'700 '+Math.round(R*0.11)+'px Georgia,serif',mat.edge);
  }else{
    circText(ctx,'TEN THOUSAND',R*0.66,'700 '+Math.round(R*0.105)+'px Georgia,serif',mat.edge,true);
    ctx.save();ctx.rotate(Math.PI);circText(ctx,'• TOKENS •',R*0.66,'700 '+Math.round(R*0.11)+'px Georgia,serif',mat.edge,true);ctx.restore();
    // wreath
    ctx.strokeStyle=mat.edge;ctx.lineWidth=R*0.015;
    ctx.beginPath();ctx.arc(0,0,R*0.52,Math.PI*0.15,Math.PI*0.85);ctx.stroke();
    ctx.beginPath();ctx.arc(0,0,R*0.52,-Math.PI*0.85,-Math.PI*0.15);ctx.stroke();
    for(var k=0;k<12;k++){
      var aa=Math.PI*(0.2+0.6*k/11);
      ctx.save();ctx.rotate(0);
      var lx=Math.cos(aa)*R*0.52, ly=Math.sin(aa)*R*0.52;
      ctx.translate(lx,ly);ctx.rotate(aa+0.6);ctx.fillStyle=mat.edge;
      ctx.beginPath();ctx.ellipse(0,0,R*0.055,R*0.028,0,0,Math.PI*2);ctx.fill();
      ctx.translate(-2*lx,-2*ly+0);ctx.translate(lx,-ly);ctx.rotate(-2*aa); 
      ctx.restore();
      var aa2=-aa;
      var lx2=Math.cos(aa2)*R*0.52, ly2=Math.sin(aa2)*R*0.52;
      ctx.save();ctx.translate(lx2,ly2);ctx.rotate(aa2-0.6);ctx.fillStyle=mat.edge;
      ctx.beginPath();ctx.ellipse(0,0,R*0.055,R*0.028,0,0,Math.PI*2);ctx.fill();ctx.restore();
    }
    embossFill('10,000',0,-R*0.06,'900 '+Math.round(R*0.30)+'px Arial,sans-serif',mat.edge);
    embossFill('TOKENS',0,R*0.22,'800 '+Math.round(R*0.13)+'px Arial,sans-serif',mat.edge);
    embossFill('— DENOMINATION —',0,R*0.38,'700 '+Math.round(R*0.07)+'px Arial,sans-serif',mat.edge);
  }
  // moving specular: rakes across as yaw changes
  var hx=R*0.58*Math.sin(yaw+0.7), hy=-R*0.38+R*0.12*Math.sin(pitch*3);
  var sg=ctx.createRadialGradient(hx,hy,0,hx,hy,R*0.62);
  sg.addColorStop(0,'rgba(255,255,255,.92)');sg.addColorStop(0.18,'rgba(255,255,255,.55)');sg.addColorStop(0.45,'rgba(255,255,255,.12)');sg.addColorStop(1,'rgba(255,255,255,0)');
  ctx.fillStyle=sg;ctx.fillRect(-R,-R,R*2,R*2);
  // diagonal sheen sweeping with yaw
  var off=0.5+0.42*Math.sin(yaw*1.0+0.3);
  var lg=ctx.createLinearGradient(-R,-R,R,R);
  lg.addColorStop(Math.max(0,off-0.22),'rgba(255,255,255,0)');
  lg.addColorStop(off,'rgba(255,255,255,.38)');
  lg.addColorStop(Math.min(1,off+0.22),'rgba(255,255,255,0)');
  ctx.fillStyle=lg;ctx.fillRect(-R,-R,R*2,R*2);
  ctx.restore();
  ctx.restore();
}

function drawCoin(ctx,W,H,yaw,pitch,mat){
  ctx.save();
  ctx.fillStyle='#0e131a';ctx.fillRect(0,0,W,H);
  var cx=W/2, cy=H/2;
  var R=Math.min(W,H)*0.31, T=R*0.15;
  var cY=Math.cos(yaw),sY=Math.sin(yaw),cP=Math.cos(pitch),sP=Math.sin(pitch);
  var nx=sY*cP, ny=-sP, nz=cY*cP;
  var dx=(T/2)*cP*sY, dy=(T/2)*sP;
  var fCx=cx+dx, fCy=cy+dy, bCx=cx-dx, bCy=cy-dy;
  var rx=R*Math.sqrt(Math.max(0,1-nx*nx)), ry=R*Math.sqrt(Math.max(0,1-ny*ny));
  var N=120, fR=[],bR=[],all=[];
  for(var i=0;i<N;i++){
    var a=i/N*Math.PI*2, ca=Math.cos(a), sa=Math.sin(a);
    var x=ca*R, y=sa*R;
    var pf=rot(x,y,T/2,cY,sY,cP,sP), pb=rot(x,y,-T/2,cY,sY,cP,sP);
    var pF={x:cx+pf.X,y:cy-pf.Y * -1 * -1 + ( -pf.Y*0 ) ,a:a}; // careful: canvas y = cy - Y? Y up. pf.Y is Y' up.
    // Actually rot Y is up-positive. Canvas y down => cy - Y
    pF={x:cx+pf.X, y:cy-pf.Y, a:a, nzSide:-ca*sY+sa*sP*cY};
    var pB={x:cx+pb.X, y:cy-pb.Y, a:a, nzSide:-ca*sY+sa*sP*cY};
    fR.push(pF);bR.push(pB);all.push(pF);all.push(pB);
  }
  var h=hull(all);
  ctx.beginPath();ctx.moveTo(h[0].x,h[0].y);
  for(var j=1;j<h.length;j++)ctx.lineTo(h[j].x,h[j].y);
  ctx.closePath();
  var eg=ctx.createLinearGradient(cx-rx,0,cx+rx,0);
  eg.addColorStop(0,mat.dark);eg.addColorStop(0.5,mat.light);eg.addColorStop(1,mat.dark);
  ctx.fillStyle=eg;ctx.fill();
  ctx.lineWidth=2;ctx.strokeStyle='rgba(0,0,0,.6)';ctx.stroke();
  // reeded edge: alternating ridges where side faces camera
  ctx.lineCap='round';
  for(var k2=0;k2<N;k2++){
    var s=fR[k2], e=bR[k2];
    if(s.nzSide>0.02){
      var ridge=(k2%2===0);
      var diff=Math.max(0,s.nzSide);
      var base=ridge?mat.hi:mat.dark;
      ctx.strokeStyle=base;ctx.globalAlpha=0.25+0.75*diff;
      ctx.lineWidth=Math.max(2, (2*Math.PI*R/N)*0.55);
      ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(e.x,e.y);ctx.stroke();
    }
  }
  ctx.globalAlpha=1;
  var frontVisible=nz>=0;
  if(frontVisible){ drawFace(ctx,fCx,fCy,rx,ry,R,mat,true,yaw,pitch,nz); }
  else{ drawFace(ctx,bCx,bCy,rx,ry,R,mat,false,yaw,pitch,nz); }
  // crisp rim light
  if(rx>2&&ry>2){
    ctx.save();ctx.translate(frontVisible?fCx:bCx,frontVisible?fCy:bCy);ctx.scale(Math.max(0.02,rx/R),Math.max(0.02,ry/R));
    ctx.beginPath();ctx.arc(0,0,R*0.985,Math.PI*1.05,Math.PI*1.95);ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=R*0.02;ctx.stroke();
    ctx.beginPath();ctx.arc(0,0,R*0.985,Math.PI*0.05,Math.PI*0.95);ctx.strokeStyle='rgba(0,0,0,.6)';ctx.lineWidth=R*0.025;ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

function renderHeroAt(t){
  var yaw=t*Math.PI*2, pitch=0.45*Math.sin(t*Math.PI*2);
  drawCoin(hctx,HW,HH,yaw,pitch,MATS.gold);
}

